--region init
function UIActivityMidFestivalBossMainDialog:InitHandler()
    SetButtonAction(self.Btncheck, Bind(self, self.OnBtnBossDetailClickHandler))
    SetButtonAction(self.BtnList, Bind(self, self.OnBtnListClickHandler))
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnRewardClickHandler))
