    ---@type MidFestivalBossPlanVo
    self._planVo = CfUtils.GetCfVo(AutoIds.IdSetting6105, "MidFestivalBossPlanVo", activityDojo.activityContentId)
    ---@type MidFestivalBossQuestVo
    self._questVo = CfUtils.GetCfVo(AutoIds.IdSetting6106, "MidFestivalBossQuestVo", self._planVo.range)

    ActivityMidFestivalBossTool.BossHomeReq()
end
