function UIActivityMidFestivalBossMainDialog:OnBtnListClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIActivityMidFestivalBossPlayerRankDialog
    })
end

function UIActivityMidFestivalBossMainDialog:OnBtnRewardClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIActivityMidFestivalBossDamageRewardRankDialog
    })
end

function UIActivityMidFestivalBossMainDialog:OnBtnFightHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIFightTeamChoose,
        parameters = {
            activityUuid = self._activityMidFestivalComponent:GetActivityDojo().id,
            levelId = self._planVo.range
        }
    }, {
        { id = Constants.UITypeIds.UIActivityMidFestivalBossDialog }
    })
end

function UIActivityMidFestivalBossMainDialog:OnBtnBossDetailClickHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIActivityMidFestivalBossDetailDialog, parameters = { planVo =  self._planVo}
    },{
        { id = Constants.UITypeIds.UIActivityMidFestivalBossDialog }
    })
end

function UIActivityMidFestivalBossMainDialog:OnBossHomeReqHandler()
    self._bossHomeDojo = self._activityMidFestivalBossComponent:GetBossHomeDojo()
    self._isOpen = false
    self:RefreshUI()
end
--endregion handler

--region private
function UIActivityMidFestivalBossMainDialog:RefreshPlayerRank()
    self._playerRankScr:Refresh()
end

function UIActivityMidFestivalBossMainDialog:RefreshUI()
    CfUtils.FillImage(self.Bg, self._planVo.modelId)
    CfUtils.FillText(self.TxtName, self._questVo.characteristic)

    CfUtils.RefreshTopGoods({})

    self:RefreshPlayerRank()
    self:RefreshRedPoint()
end

function UIActivityMidFestivalBossMainDialog:RefreshRedPoint()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local hasRedPoint = homeDojo.bossHurtTips == 0
    CfUtils.SetActive(self.BtnReward.transform:Find("redPoint"), hasRedPoint)
end
